<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$month=(string)($_GET['month']??date('Y-m'));if(!valid_month($month))$month=date('Y-m');$type=(string)($_GET['type']??'all');if(!in_array($type,['all','income','expense'],true))$type='all';$q=trim((string)($_GET['q']??''));$start=$month.'-01';$end=date('Y-m-d',strtotime($start.' +1 month'));$sql='SELECT * FROM transactions WHERE transaction_date>=:s AND transaction_date<:e';$params=['s'=>$start,'e'=>$end];if($type!=='all'){$sql.=' AND type=:type';$params['type']=$type;}if($q!==''){$sql.=' AND (title LIKE :q OR category LIKE :q OR notes LIKE :q)';$params['q']='%'.$q.'%';}$sql.=' ORDER BY transaction_date DESC,id DESC';$s=$pdo->prepare($sql);$s->execute($params);$items=$s->fetchAll();$pageTitle='Transactions — ExpenseWise';require __DIR__.'/includes/header.php';?><div class="app-shell"><?php require __DIR__.'/includes/sidebar.php';?><main class="main-area"><header class="topbar"><div><p class="breadcrumb">Workspace / Transactions</p><h1>Every transaction, in one place.</h1></div><a class="button primary" href="create.php">＋ Add transaction</a></header><?php if($f=take_flash()):?><div class="notice <?=e($f['type'])?>"><?=e($f['message'])?></div><?php endif;?><section class="panel recent"><div class="panel-heading"><div><h2>Transaction history</h2><p>Search and filter your records</p></div></div><form class="toolbar"><input type="month" name="month" value="<?=e($month)?>"><input type="search" name="q" value="<?=e($q)?>" placeholder="Search title, category or notes"><select name="type"><option value="all">All types</option><option value="income" <?=$type==='income'?'selected':''?>>Income</option><option value="expense" <?=$type==='expense'?'selected':''?>>Expense</option></select><button class="button soft">Filter</button><a class="report-link" href="transactions.php">Clear</a></form><?php if(!$items):?><div class="empty"><strong>No transactions found.</strong><p>Change your filters or add a transaction.</p></div><?php else:?><div class="table-scroll"><table><thead><tr><th>TRANSACTION</th><th>CATEGORY</th><th>DATE</th><th>PAYMENT</th><th class="right">AMOUNT</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($items as $t):?><tr><td><b><?=e($t['title'])?></b><small><?=e(ucfirst($t['type']))?></small></td><td><span class="pill"><?=e($t['category'])?></span></td><td><?=e(date('M j, Y',strtotime($t['transaction_date'])))?></td><td><?=e($t['payment_method'])?></td><td class="right <?=$t['type']==='income'?'green':''?>"><?=$t['type']==='income'?'+':'−'?><?=money((float)$t['amount'])?></td><td><div class="actions"><a href="edit.php?id=<?=(int)$t['id']?>">Edit</a><form method="post" action="delete.php" data-confirm="Delete this transaction?"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$t['id']?>"><button>Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><footer class="app-footer">ExpenseWise <span>Personal finance, made clearer.</span></footer></main></div><?php require __DIR__.'/includes/footer.php';?>
